      "content": "[build-system]\nrequires = [\"hatchling\"]\nbuild-backend = \"hatchling.build\"\n\n[project]\nname = \"openbiliclaw\"\nversion = \"0.3.232\"\ndescription = \"Your local-first, cross-platform AI discovery friend for Bilibili, Zhihu, and more.\"\nreadme = \"README.md\"\nlicense = { text = \"MIT\" }\nrequires-python = \">=3.11\"\nauthors = [\n    { name = \"OpenBiliClaw Contributors\" },\n]\nkeywords = [\"bilibili\", \"zhihu\", \"ai\", \"agent\", \"recommendation\", \"content-discovery\", \"cross-platform\", \"llm\"]\nclassifiers = [\n    \"Development Status :: 2 - Pre-Alpha\",\n    \"Intended Audience :: End Users/Desktop\",\n    \"License :: OSI Approved :: MIT License\",\n    \"Programming Language :: Python :: 3\",\n    \"Programming Language :: Python :: 3.11\",\n    \"Programming Language :: Python :: 3.12\",\n    \"Programming Language :: Python :: 3.13\",\n    \"Topic :: Multimedia :: Video\",\n]\n\ndependencies = [\n    \"httpx[socks]>=0.28\",\n    # Already installed by HTTPX; identify its CA bundle for image TLS reuse.\n    \"certifi\",\n    # Public network-backend API pins cover-image connections against DNS rebinding.\n    \"httpcore>=1.0,<2\",\n    \"scrapetube>=2.1\",\n    \"yt-dlp>=2024.1.0\",\n    # TikTok web API backend (sources/tiktok_web.py): Chrome TLS impersonation\n    # — TikTok's edge rejects plain-OpenSSL clients. Also an optional yt-dlp\n    # dependency, so the version lines stay compatible by construction.\n    \"curl-cffi>=0.15\",\n    \"bilibili-api-python>=16\",\n    # openai>=3 / anthropic>=1 vendor httpx internally as ``httpx2`` and their\n    # isinstance guard rejects plain ``httpx.AsyncClient`` instances passed via\n    # ``http_client=`` (openai_provider.py / claude_provider.py proxy support),\n    # so keep both on the 2.x / 0.x lines until the providers migrate.\n    \"openai>=1.0,<3\",\n    \"anthropic>=0.40,<1\",\n    \"google-genai>=1.66\",\n    # X (Twitter) discovery uses the import package ``twitter_cli``. Keep it in\n    # the default install so enabling [sources.twitter] never fails at runtime.\n    \"twitter-cli>=0.8.5\",\n    # Reddit steady-state discovery uses the ``rdt`` console command. Keep it in\n    # the default install so [sources.reddit].backend=\"rdt\" works out of the box.\n    \"rdt-cli>=0.4.1\",\n    # Runtime-stream WebSockets are a core API used by the extension and web UI.\n    \"websockets>=13\",\n    # Runtime cover-image preprocessing imports PIL directly.\n    \"Pillow>=10.0\",\n    # Blue Fish Lab renders the account QR login code server-side (SVG) so the\n    # desktop / popup panels can show it without bundling a JS QR encoder.\n    # Already pulled in by bilibili-api-python; declared because we import it.\n    \"qrcode>=8\",\n    \"fastapi>=0.115\",\n    \"rich>=13\",\n    \"typer>=0.12\",\n    # Multiline chat input (issue #83): PromptSession with custom key bindings.\n    \"prompt_toolkit>=3.0\",\n    \"pydantic>=2.0\",\n    \"apscheduler>=3.10\",\n    \"uvicorn>=0.32\",\n]\n\n[project.optional-dependencies]\ndev = [\n    \"pytest>=8\",\n    \"pytest-asyncio>=0.24\",\n    \"pytest-cov>=5\",\n    \"ruff>=0.8\",\n    \"mypy>=1.13\",\n    # Build-time generator for the Traditional Chinese UI catalog\n    # (scripts/build_i18n_catalogs.py). The runtime never imports it.\n    \"opencc-python-reimplemented>=0.1.7\",\n]\nlocal-llm = [\n    \"ollama>=0.4\",\n]\nx = [\n    # Backwards-compatible alias for users/scripts that already install\n    # ``openbiliclaw[x]``. The dependency is also part of the default runtime set.\n    \"twitter-cli>=0.8.5\",\n]\neval = [\n    \"claude-agent-sdk>=0.1\",\n]\nbrowser = [\n    \"playwright>=1.40\",\n]\ntls = [\n    \"cryptography>=41\",\n]\npackaging = [\n    # Desktop installer builds (packaging/build.py). Bundles the backend into a\n    # macOS .app/.dmg or Windows onedir for the Inno Setup installer.\n    \"pyinstaller>=6.11\",\n    # System-tray desktop mode (packaging/entry.py): tray icon + menu so the app\n    # runs without a console window — Windows system tray and macOS menu bar.\n    \"pystray>=0.19\",\n    # pystray's macOS backend needs pyobjc (Foundation / AppKit / Quartz).\n    \"pyobjc-framework-Cocoa>=10.0; sys_platform == 'darwin'\",\n    \"pyobjc-framework-Quartz>=10.0; sys_platform == 'darwin'\",\n]\n\n[project.scripts]\nopenbiliclaw = \"openbiliclaw.cli:app\"\n\n[project.urls]\nHomepage = \"https://github.com/whiteguo233/OpenBiliClaw\"\nRepository = \"https://github.com/whiteguo233/OpenBiliClaw\"\nIssues = \"https://github.com/whiteguo233/OpenBiliClaw/issues\"\n\n[tool.hatch.build.targets.wheel]\npackages = [\"src/openbiliclaw\"]\n\n[tool.ruff]\ntarget-version = \"py311\"\nline-length = 100\nsrc = [\"src\", \"tests\"]\n\n[tool.ruff.lint]\nselect = [\n    \"E\",    # pycodestyle errors\n    \"W\",    # pycodestyle warnings\n    \"F\",    # pyflakes\n    \"I\",    # isort\n    \"N\",    # pep8-naming\n    \"UP\",   # pyupgrade\n    \"B\",    # flake8-bugbear\n    \"SIM\",  # flake8-simplify\n    \"TCH\",  # flake8-type-checking\n]\n\n[tool.ruff.lint.per-file-ignores]\n\"src/openbiliclaw/llm/prompts.py\" = [\"E501\"]  # Prompt templates contain long JSON examples\n\"src/openbiliclaw/llm/prompts_pipeline.py\" = [\"E501\"]\n\"scripts/*.py\" = [\"E501\"]  # Scripts contain long prompt strings\n\n[tool.mypy]\npython_version = \"3.11\"\nstrict = true\nwarn_return_any = true\nwarn_unused_configs = true\n\n[[tool.mypy.overrides]]\nmodule = [\n    \"aiohttp\",\n    \"claude_agent_sdk\",\n    \"claude_agent_sdk.*\",\n    \"playwright.*\",\n    \"qrcode\",\n    \"qrcode.*\",\n    \"twitter_cli\",\n    \"twitter_cli.*\",\n    \"x_client_transaction\",\n    \"x_client_transaction.*\",\n]\nignore_missing_imports = true\n\n[tool.pytest.ini_options]\ntestpaths = [\"tests\"]\nasyncio_mode = \"auto\"\nmarkers = [\n    \"integration: real Bilibili API checks that require local credentials\",\n]\n"
